/**
 * Process-local owners of hop ids.
 *
 * Downstream services that copy inbound `X-Mockifyer-Request-Id` without minting a
 * new id reuse the caller's id. The dashboard proxy (and in-process Mockifyer)
 * uses this registry so that reused id becomes the **parent**, not this hop.
 */
export interface HopOwnerRecord {
    requestId: string;
    method: string;
    url: string;
    /**
     * Outbound headers as sent (lowercased names). Kept so Atlas can rebuild a
     * runnable request for this hop; never posted to the dashboard unredacted.
     */
    requestHeaders?: Record<string, string>;
}
export interface RecordedHopIdentity {
    requestId: string;
    parentRequestId?: string;
}
export interface ResolveRecordedHopIdentityInput {
    inboundRequestId?: string | null;
    inboundParentRequestId?: string | null;
    method: string;
    url: string;
    storedRequestId?: string | null;
}
/** Method + pathname so relative and absolute forms of the same hop still match. */
export declare function hopOwnerEndpointKey(method: string, url: string): string;
export declare function sameHopOwnerEndpoint(a: Pick<HopOwnerRecord, 'method' | 'url'>, b: Pick<HopOwnerRecord, 'method' | 'url'>): boolean;
export declare function findHopOwner(requestId: string | null | undefined): HopOwnerRecord | undefined;
/** Remember which endpoint minted or is serving this hop id. */
export declare function registerHopOwner(record: HopOwnerRecord): void;
/** Outbound headers recorded for a hop id (Atlas curl rebuild). */
export declare function findHopRequestHeaders(requestId: string | null | undefined): Record<string, string> | undefined;
/** Test helper — hop-id ownership is process-global. */
export declare function resetHopOwnerRegistry(): void;
/**
 * True when `inboundRequestId` already identifies a **different** endpoint's hop
 * (caller forwarded its own id instead of minting a child id).
 */
export declare function inboundHopIdBelongsToOtherEndpoint(inboundRequestId: string | null | undefined, method: string, url: string): boolean;
/**
 * Exact hop identity for a recorded/proxied request.
 *
 * - Caller already minted this hop (inbound id is new or owned by this endpoint): keep it.
 * - Caller forwarded their hop id (owned by another endpoint): that id is the parent;
 *   this hop gets the stored id or a new one.
 */
export declare function resolveRecordedHopIdentity(input: ResolveRecordedHopIdentityInput): RecordedHopIdentity;
